package cn.cccs7.cynexus.market.application.service;
import cn.cccs7.cynexus.market.api.dto.MarketFactorSetDTO; import cn.cccs7.cynexus.market.domain.factorresearch.*; import java.util.*; import org.springframework.stereotype.Service;
@Service public class MarketFactorSetAppService {
 private final MarketFactorSetDomainService domain; public MarketFactorSetAppService(MarketFactorSetDomainService domain){this.domain=domain;}
 public MarketFactorSetDTO.ListResponse list(MarketFactorSetBO.Scope s,int o,int l){return new MarketFactorSetDTO.ListResponse(domain.list(s,o,l).stream().map(this::response).toList());}
 public MarketFactorSetDTO.Response get(MarketFactorSetBO.Scope s,String c){return response(domain.get(s,c));}
 public MarketFactorSetDTO.Response create(MarketFactorSetBO.Scope s,MarketFactorSetDTO.CreateRequest r){return response(domain.create(s,new MarketFactorSetBO.CreateCommand(r.getCode(),r.getName(),r.getExpression(),r.getSourceStudyId())));}
 public MarketFactorSetDTO.Response update(MarketFactorSetBO.Scope s,String c,MarketFactorSetDTO.UpdateRequest r){return response(domain.update(s,c,new MarketFactorSetBO.UpdateCommand(r.getName(),r.getExpression(),r.getSourceStudyId(),r.getExpectedVersion()==null?-1:r.getExpectedVersion())));}
 public MarketFactorSetDTO.Version validate(MarketFactorSetBO.Scope s,String c,MarketFactorSetDTO.ValidateRequest r){return version(domain.validate(s,c,r.getVersionNo(),r.getValidationSnapshot()));}
 public MarketFactorSetDTO.Version promote(MarketFactorSetBO.Scope s,String c,int n){return version(domain.promote(s,c,n));}
 public MarketFactorSetDTO.PreviewResponse preview(MarketFactorSetBO.Scope s,String c,int n,MarketFactorSetDTO.PreviewRequest r){var v=domain.preview(s,c,n,r==null||r.getTradeDate()==null||r.getTradeDate().isBlank()?java.time.LocalDate.now():java.time.LocalDate.parse(r.getTradeDate()),r==null||r.getLimit()==null?50:r.getLimit());return MarketFactorSetDTO.PreviewResponse.builder().factorSetVersionId(v.factorSetVersionId()).code(v.code()).versionNo(v.versionNo()).requestedTradeDate(v.requestedTradeDate().toString()).snapshotTradeDate(v.snapshotTradeDate()==null?null:v.snapshotTradeDate().toString()).status(v.status()).count(v.count()).items(v.items().stream().map(i->MarketFactorSetDTO.PreviewItem.builder().code(i.code()).name(i.name()).market(i.market()).industry(i.industry()).price(i.price()).changePct(i.changePct()).reason(i.reason()).build()).toList()).warnings(v.warnings()).build();}
 public MarketFactorSetDTO.StrategyHandoffResponse strategyHandoff(MarketFactorSetBO.Scope s,String c,int n){MarketFactorSetBO.Version v=domain.requirePromotedForStrategy(s,c,n);return MarketFactorSetDTO.StrategyHandoffResponse.builder().factorSetCode(c).factorSetVersionId(v.id()).versionNo(v.versionNo()).sourceStudyId(v.sourceStudyId()).expression(v.expression()).status(v.status().name()).build();}
 private MarketFactorSetDTO.Response response(MarketFactorSetBO.Definition d){return MarketFactorSetDTO.Response.builder().id(d.id()).code(d.code()).name(d.name()).status(d.status().name()).activeVersionId(d.activeVersionId()).version(d.version()).activeVersion(d.activeVersion()==null?null:version(d.activeVersion())).build();}
 private MarketFactorSetDTO.Version version(MarketFactorSetBO.Version v){return MarketFactorSetDTO.Version.builder().id(v.id()).versionNo(v.versionNo()).status(v.status().name()).expression(v.expression()).validationSnapshot(v.validationSnapshot()).build();}
}
